import { setupRag } from './rag.js';
import { buildReviewViewModel, getReviewStatus } from './review-visualization.js';
const $ = (s, root = document) => root.querySelector(s);
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',file:'<path d="M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h6"/>',book:'<path d="M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2v16"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',alert:'<path d="m12 3 10 18H2zM12 9v5M12 17h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',layers:'<path d="m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',external:'<path d="M14 3h7v7m0-7-10 10M10 3H3v18h18v-7"/>'};
const icon = n => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n] || icons.file}</svg>`;
const labels = {pass:'通過',error:'疑似錯誤',pending:'待確認',missing:'資料不足'};
const totalNames={normal_price:'土地正常單價（元／㎡）',time_rate:'日期調整率（%）',adjusted_price:'估價基準日單價（元／㎡）',regional_detail:'表 5-2 區域總修正數（%）',regional_carried:'表 4 區域調整率（%）',individual:'個別因素合計（%）',absolute:'調整率絕對值加總（%）',trial_price:'試算價格（元／㎡）',weight:'比較標的權重（%）'};
const state={view:'home',cases:[],rulesets:[],current:null,review:null,doc:null,tab:'checks',filter:'all',scope:'individual',page:3,sourceMode:'pdf',quote:'',dirty:false,health:{},search:'',ruleSearch:'',rulesetDraft:null,pendingRulesetId:null};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6000)}
async function api(url,options={}){const res=await fetch(url,{...options,headers:options.body && typeof options.body==='string'?{'Content-Type':'application/json',...options.headers}:options.headers});if(!res.ok){let text=await res.text();try{const j=JSON.parse(text);text=typeof j.detail==='string'?j.detail:JSON.stringify(j.detail)}catch{}throw new Error(text.slice(0,500))}return res.json()}
async function busy(message,fn){const el=document.createElement('div');el.className='busy-overlay';el.setAttribute('role','status');el.innerHTML=`<span class="spinner"></span><span>${esc(message)}</span>`;document.body.append(el);try{return await fn()}catch(e){toast(e.message);return null}finally{el.remove()}}
const pill=(status,text)=>`<span class="pill ${status}">${esc(text || labels[status])}</span>`;
const fmt=x=>x==null?'—':Number(x).toLocaleString('zh-TW',{maximumFractionDigits:2});
// UI feedback mirrors the server policy; the domain remains authoritative.
const confirmationContext=new Set(['ruleset_id','document_id','locality','land_use','valuation_date','subject_name','comparable_name','subject_address','comparable_address','subject_section','comparable_section']);
function resetConfirmationBlocks(){state.confirmationBlocks={all:false,factors:new Set(),totals:false}}
resetConfirmationBlocks();
function invalidateConfirmation(kind,id){
 const blocked=state.confirmationBlocks;
 if(kind==='all'){blocked.all=true;for(const f of state.current.factors)f.confirmed=false}
 if(kind==='factor'){blocked.factors.add(id);const f=state.current.factors.find(f=>f.id===id);if(f)f.confirmed=false}
 blocked.totals=true;state.current.totals_confirmed=false;
 syncConfirmationControls();
}
function syncConfirmationControls(){
 for(const el of document.querySelectorAll('[data-factor][data-key="confirmed"]')){
  el.checked=!!state.current.factors.find(f=>f.id===el.dataset.factor)?.confirmed;
  el.disabled=state.confirmationBlocks.all||state.confirmationBlocks.factors.has(el.dataset.factor);
 }
 const totals=document.querySelector('[data-case="totals_confirmed"]');
 if(totals){totals.checked=state.current.totals_confirmed;totals.disabled=state.confirmationBlocks.totals}
}
const activeRules=()=>state.rulesets.find(r=>r.id===state.current?.ruleset_id)||state.rulesets[0];
function shell(body){return `<div class="shell"><aside class="sidebar"><a class="brand" href="#" data-action="home"><span class="brand-mark">${icon('layers')}</span><span><b>地衡</b><small>LANDWISE</small></span></a><div class="navlabel">WORKSPACE</div><button class="navitem ${state.view==='home'||state.view==='case'?'active':''}" data-action="home">${icon('grid')}案件工作台<span class="count">${state.cases.length}</span></button><button class="navitem ${state.view==='rules'?'active':''}" data-action="rules">${icon('book')}評價基準庫</button><button class="navitem ${state.view==='guide'?'active':''}" data-action="guide">${icon('file')}使用指南</button><div class="sidebar-bottom"><span class="pill neutral"><span class="dot"></span>本機工作空間</span><p>政府機關估價案件<br>輔助審查工作台</p><p class="product-version">LANDWISE / MVP 1.0</p></div></aside><main class="workspace" id="main-content"><header class="topbar"><span class="crumb">工作空間 <span class="crumb-divider">/</span> ${state.view==='case'?'案件審查':state.view==='rules'?'評價基準庫':state.view==='guide'?'使用指南':'案件工作台'}</span><span class="right"><span><span class="dot"></span>資料儲存於本機</span><span class="avatar">審</span></span></header><div class="content">${body}</div></main></div>`}
function render(){const body=state.view==='home'?home():state.view==='case'?workspace():state.view==='rules'?rulesPage():guide();$('#app').innerHTML=shell(body);if(state.view==='case')renderSource()}
function metric(label,value,sub,ic){return `<div class="metric"><span class="icon">${icon(ic)}</span><div class="label">${label}</div><strong>${value}</strong><small>${sub}</small></div>`}
const factorRowId=id=>'review-factor-'+encodeURIComponent(String(id));
const displayValue=value=>value===null||value===undefined||value===''?'目前無資料':esc(value);
const displayPair=(left,right,unit='')=>`<span><small>比準地</small>${displayValue(left)}${left!==null&&left!==undefined&&left!==''&&unit?' '+esc(unit):''}</span><span><small>比較標的</small>${displayValue(right)}${right!==null&&right!==undefined&&right!==''&&unit?' '+esc(unit):''}</span>`;
const displayRate=value=>value===null||value===undefined||value===''?'目前無資料':`${fmt(value)}%`;
const compactValue=value=>value===null||value===undefined||value===''?'<span class="compact-missing" title="目前無資料">—</span>':esc(value);
const compactPair=(left,right,unit='')=>`<span><small>比準地</small>${compactValue(left)}${left!==null&&left!==undefined&&left!==''&&unit?' '+esc(unit):''}</span><span><small>比較標的</small>${compactValue(right)}${right!==null&&right!==undefined&&right!==''&&unit?' '+esc(unit):''}</span>`;
const compactRate=value=>value===null||value===undefined||value===''?'<span class="compact-missing" title="目前無資料">—</span>':`${fmt(value)}%`;
function reviewStatus(status){const meta=getReviewStatus(status);return `<span class="review-status ${esc(status)}"><span aria-hidden="true">${meta.icon}</span>${esc(meta.label)}</span>`}
function reviewViewModel(){return buildReviewViewModel({caseData:state.current,review:state.review,ruleset:activeRules()})}
function reviewOverview(vm){
 const {counts,total,overallStatus,overall}=vm.summary;
 const issueSummary=overallStatus==='pass'
  ? '所有可驗證項目皆符合目前規則。'
  : `發現 ${counts.error} 個不一致、${counts.pending} 個待人工確認、${counts.missing} 個缺資料。`;
 const keyIssues=vm.issues.slice(0,3);
 const metrics=[
  ['total','總檢核項目',total,'項'],
  ['pass','通過',counts.pass,'項'],
  ['error','不一致',counts.error,'項'],
  ['pending','待人工確認',counts.pending,'項'],
  ['missing','缺資料',counts.missing,'項'],
 ];
 return `<section class="review-overview" aria-labelledby="review-overview-title"><article class="overall-status-card ${esc(overallStatus)}"><div class="overall-status-heading"><span class="overall-status-icon" aria-hidden="true">${overall.icon}</span><div><p class="section-kicker">整體審查狀態</p><h2 id="review-overview-title">${esc(overall.overall)}</h2></div></div><p class="overall-status-copy">${esc(issueSummary)}</p>${keyIssues.length?`<div class="overall-key-issues"><span>主要問題</span><ul>${keyIssues.map(issue=>`<li>${esc(issue.title)}：${esc(issue.message)}</li>`).join('')}</ul></div>`:''}</article><div class="review-summary-grid" aria-label="審查結果統計">${metrics.map(([status,label,value,suffix])=>`<article class="review-summary-item ${status}"><span class="summary-symbol" aria-hidden="true">${status==='total'?'#':getReviewStatus(status).icon}</span><strong>${value}</strong><span>${esc(label)}</span><small>${suffix}</small></article>`).join('')}</div></section>`;
}
function reviewIssueList(vm){
 const issues=vm.issues;
 return `<section class="review-panel review-issue-panel" aria-labelledby="review-issues-title"><div class="review-panel-head"><div><p class="section-kicker">需要處理</p><h2 id="review-issues-title">問題與待確認項目</h2></div><span class="panel-count">${issues.length} 項</span></div><div class="review-groups" aria-label="動態審查分類">${vm.groups.map(group=>`<div class="review-group-row"><span>${esc(group.name)} <small>${group.count} 項</small></span>${reviewStatus(group.status)}</div>`).join('')}</div>${issues.length?`<div class="review-issue-list">${issues.map(issue=>`<article class="review-issue ${esc(issue.status)}"><div class="issue-status-icon" aria-hidden="true">${issue.statusMeta.icon}</div><div class="issue-content"><div class="issue-title-row"><h3>${esc(issue.title)}</h3>${reviewStatus(issue.status)}</div><p>${esc(issue.message)}</p>${issue.actual!==null||issue.expected!==null?`<dl class="issue-values"><div><dt>表單／原填</dt><dd>${displayValue(issue.actual)}</dd></div><div><dt>系統現有結果</dt><dd>${displayValue(issue.expected)}</dd></div></dl>`:''}</div><button class="text-action" data-action="${issue.factorId?'focus-review-factor':'focus-checks'}" data-id="${esc(issue.factorId||issue.status)}">查看詳情 <span aria-hidden="true">→</span></button></article>`).join('')}</div>`:'<div class="review-empty success"><span aria-hidden="true">✓</span><div><strong>目前沒有需要處理的項目</strong><p>所有可驗證項目皆已通過。</p></div></div>'}</section>`;
}
function mapReviewPanel(vm){
 return `<section class="review-panel map-review-panel" aria-labelledby="map-review-title"><div class="review-panel-head"><div><p class="section-kicker">位置資料</p><h2 id="map-review-title">案件區域</h2></div><span class="data-origin">現有案件資料</span></div><div class="map-unavailable" role="img" aria-label="目前無座標與地價區段邊界資料"><span class="map-pin" aria-hidden="true">⌖</span><strong>目前無法顯示地圖定位</strong><p>${displayValue(vm.map.address)}</p><small>${displayValue(vm.map.locality)}</small><div class="map-data-note">目前尚無座標與地價區段邊界資料<br>目前無周邊設施位置資料</div></div><div class="map-legend" aria-label="審查狀態圖例">${['pass','pending','error','missing'].map(status=>`<span><i class="${status}" aria-hidden="true"></i>${esc(getReviewStatus(status).label)}</span>`).join('')}</div></section>`;
}
function factorReviewTable(vm){
 const populated=vm.populatedFactors,empty=vm.emptyFactors;
 const table=populated.length?`<div class="factor-table-wrap"><table class="factor-review-table"><thead><tr><th>因素</th><th>類別</th><th>原始值</th><th>表單等級</th><th>系統等級</th><th>表單修正率</th><th>系統修正率</th><th>狀態</th><th>操作</th></tr></thead><tbody>${populated.map(factor=>`<tr id="${factorRowId(factor.id)}" class="factor-review-row ${esc(factor.status)}" tabindex="0" data-action="open-review-factor" data-id="${esc(factor.id)}" aria-label="${esc(factor.name)}，${esc(factor.statusMeta.label)}"><td data-label="因素"><strong>${esc(factor.name)}</strong><small>${esc(factor.scopeLabel)}</small></td><td data-label="類別">${esc(factor.group)}</td><td data-label="原始值"><div class="paired-values">${compactPair(factor.subjectValue,factor.comparableValue,factor.unit)}</div></td><td data-label="表單等級"><div class="paired-values">${compactPair(factor.enteredSubjectGrade,factor.enteredComparableGrade)}</div></td><td data-label="系統等級"><div class="paired-values">${compactPair(factor.systemSubjectGrade,factor.systemComparableGrade)}</div></td><td data-label="表單修正率" class="number-cell">${compactRate(factor.enteredRate)}</td><td data-label="系統修正率" class="number-cell">${compactRate(factor.expectedRate)}</td><td data-label="狀態">${reviewStatus(factor.status)}</td><td data-label="操作"><button class="table-action" data-action="open-review-factor" data-id="${esc(factor.id)}" aria-label="查看 ${esc(factor.name)} 詳情">詳情</button></td></tr>`).join('')}</tbody></table></div>`:'';
 const emptyState=!populated.length&&empty.length?`<div class="factor-empty-state"><span class="factor-empty-icon" aria-hidden="true">${icon('file')}</span><div class="factor-empty-content"><p class="section-kicker">等待案件資料</p><h3>目前只有評價規則，尚未有案件數值</h3><p>系統已載入 ${vm.factors.length} 項評價因素，但題目欄位尚未匯入或尚未完成對應。為避免誤判，系統不會自動補零或推測等級。</p><div class="empty-data-flow" aria-label="資料處理進度"><div class="complete"><span>1</span><strong>評價基準</strong><small>已就緒</small></div><i aria-hidden="true"></i><div class="current"><span>2</span><strong>題目資料</strong><small>尚未取得</small></div><i aria-hidden="true"></i><div><span>3</span><strong>系統審查</strong><small>等待資料</small></div></div><div class="factor-empty-actions"><button class="primary" data-action="upload">${icon('upload')}上傳題目</button>${empty[0]?.editable?`<button class="ghost" data-action="edit-factor" data-id="${esc(empty[0].id)}">前往資料核對</button>`:''}</div></div></div>`:'';
 const missingNotice=populated.length&&empty.length?`<div class="factor-missing-notice"><span aria-hidden="true">${getReviewStatus('missing').icon}</span><p><strong>${empty.length} 項因素尚未取得案件資料</strong><small>已收合在下方，不影響目前有資料項目的閱讀。</small></p></div>`:'';
 const missingGroups=empty.length?`<details class="missing-factor-disclosure"><summary><span><strong>尚有 ${empty.length} 項因素待填</strong><small>依評價基準分類查看</small></span><span class="disclosure-mark" aria-hidden="true">＋</span></summary><div class="missing-factor-groups">${vm.emptyGroups.map(group=>`<section class="missing-factor-group"><h3>${esc(group.name)}<span>${group.factors.length}</span></h3><div class="missing-factor-tags">${group.factors.map(factor=>factor.editable?`<button data-action="edit-factor" data-id="${esc(factor.id)}">${esc(factor.name)}</button>`:`<span>${esc(factor.name)}</span>`).join('')}</div></section>`).join('')}</div></details>`:'';
 const noFactors=!vm.factors.length?'<div class="review-empty"><span aria-hidden="true">−</span><div><strong>目前沒有因素資料</strong><p>請先確認案件綁定的評價基準。</p></div></div>':'';
 return `<section class="review-panel factor-review-section" aria-labelledby="factor-review-title"><div class="review-panel-head"><div><p class="section-kicker">審查資料</p><h2 id="factor-review-title">因素審查明細</h2></div><span class="data-origin">${populated.length} 項有資料 · ${empty.length} 項待填</span></div>${emptyState}${table}${missingNotice}${missingGroups}${noFactors}</section>`;
}
function reviewDashboard(vm){return `${reviewOverview(vm)}<div class="review-insight-grid">${reviewIssueList(vm)}${mapReviewPanel(vm)}</div>${factorReviewTable(vm)}`}
function home(){const all=state.cases;const issues=all.filter(c=>c.counts.error).length;const pending=all.filter(c=>c.counts.pending+c.counts.missing).length;const factors=state.rulesets.reduce((sum,r)=>sum+(r.rules?.length||0),0);return `<div class="title-row"><div><div class="eyebrow">CASE WORKSPACE</div><h1>案件工作台</h1><p class="subtitle">讓每一項估價判定，都有清楚的依據。</p></div><div class="actions"><button data-action="new">${icon('plus')}建立案件</button><button data-action="upload">${icon('upload')}上傳題目</button><button class="primary" data-action="ruleset-upload">${icon('book')}上傳評價基準表</button></div></div><section class="hero"><div><div class="eyebrow">FROM DOCUMENTS TO DECISIONS</div><h2>繁複的書表，清楚的審查。</h2><p>先將特定地區的評價基準轉成規則與檢索來源，<br>再上傳題目，自動整理地址、欄位與審查結果。</p></div><div class="steps"><div class="step"><span>${icon('book')}</span>上傳基準</div><div class="step-line"></div><div class="step"><span>${icon('upload')}</span>上傳題目</div><div class="step-line"></div><div class="step"><span>${icon('check')}</span>核對與匯出</div></div></section><div class="metrics">${metric('全部案件',all.length,'含內建範例與匯入案件','file')}${metric('有疑似錯誤',issues,'待核對修正率與計算結果','alert')}${metric('待人工確認',pending,'資料或基準尚未完成確認','clock')}${metric('可用評價基準',state.rulesets.length,`${factors} 項 ruleset 因素`,'book')}</div><div class="section-head"><h2>最近案件 <span class="muted" style="font-size:11px;margin-left:8px;font-weight:400">${all.length} 件</span></h2><label class="search">${icon('search')}<input id="case-search" aria-label="搜尋案件" placeholder="搜尋案件名稱或案號" value="${esc(state.search)}"></label></div><div class="panel" id="case-list">${caseTable()}</div><div class="footnote"><span>OCR 草稿、地址與欄位都必須由承辦人核對後確認。</span><button class="ghost small" data-action="json-import">匯入案件 JSON ${icon('arrow')}</button></div><div class="bottom-grid"><div class="help-card"><span class="icon">${icon('spark')}</span><div><h3>用一份範例，走完審查流程</h3><p>打開錯誤示範，查看修正率、加總與跨表差異，<br>採用建議後立即重新檢核。</p><button class="ghost small" data-action="demo">建立錯誤示範 ${icon('arrow')}</button></div></div><div class="help-card"><span class="icon">${icon('book')}</span><div><h3>每個案件，都有自己的基準</h3><p>上傳各地評價基準、確認矩陣方向並建立版本，<br>原始 PDF 會自動成為該版本的檢索來源。</p><button class="ghost small" data-action="rules">前往評價基準庫 ${icon('arrow')}</button></div></div></div>`}
function caseTable(){const list=state.cases.filter(c=>(c.title+c.case_number).toLowerCase().includes(state.search.toLowerCase()));return list.length?`<table class="case-table"><thead><tr><th>案件名稱 / 案號</th><th>審查狀態</th><th>待處理項目</th><th>最近更新</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><div class="case-name"><span class="file-icon">${icon('file')}</span><div><b>${esc(c.title)}</b><small>${esc(c.case_number || '尚未填寫案號')}${c.demo?' · 人工植入錯誤':''}</small></div></div></td><td>${c.counts.error?pill('error',`${c.counts.error} 項疑似錯誤`):c.counts.pending+c.counts.missing?pill('pending','待人工確認'):pill('pass','檢核通過')}</td><td><span class="muted smalltext">${c.counts.pending+c.counts.missing} 項待確認 / 不足</span></td><td><span class="muted smalltext">${new Date(c.updated).toLocaleDateString('zh-TW')}</span></td><td><button class="ghost small" data-action="open" data-id="${esc(c.id)}" aria-label="開啟 ${esc(c.title)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">沒有符合的案件。可匯入 PDF 或建立新案件。</div>'}
function workspace(){
 const c=state.current,vm=reviewViewModel();
 return `<button class="ghost small back" data-action="home">${icon('back')}返回案件工作台</button><header class="review-case-header"><div class="review-case-title"><div class="eyebrow">CASE REVIEW / ${esc(c.case_number||'DRAFT')}</div><h1>${esc(c.title)}</h1><p>${esc(c.subject_name||'未填比準地')} <span aria-hidden="true">↔</span> ${esc(c.comparable_name||'未填比較標的')} · 版本 ${c.revision}</p></div><div class="actions"><button data-action="rag">依據問答</button><button data-action="copy">${icon('plus')}複製案件</button><button data-action="audit">${icon('clock')}修訂紀錄</button><button class="primary" data-action="export">${icon('download')}匯出成果</button></div><dl class="review-case-meta"><div><dt>案件地址</dt><dd>${displayValue(vm.case.address)}</dd></div><div><dt>適用地區</dt><dd>${displayValue(vm.case.locality)}</dd></div><div><dt>用地類別</dt><dd>${displayValue(vm.case.landUse)}</dd></div><div><dt>規則來源</dt><dd>${displayValue(vm.ruleset.name)} · v${displayValue(vm.ruleset.version)}</dd></div></dl></header>${c.demo?'<div class="notice">此為人工植入錯誤的示範案件。原始 PDF 保持不變，編輯值與 PDF 的差異為測試情境。</div>':''}${c.extraction_warnings.length?`<div class="notice info">${c.extraction_warnings.map(esc).join('<br>')}</div>`:''}${reviewDashboard(vm)}<section class="full-review-section" id="full-review-workspace" aria-labelledby="full-review-title"><div class="section-title-block"><p class="section-kicker">核對與編輯</p><h2 id="full-review-title">原始文件與完整審查</h2><p>保留既有核對、修正、AI 草稿與儲存流程；上方總覽不會重新計算任何結果。</p></div><div class="review-layout"><section class="panel source-panel"><div class="panel-head"><h3>${icon('file')} 原始文件與依據</h3><button class="ghost small" data-action="source-mode">${state.sourceMode==='pdf'?'文字版':'PDF 版'}</button></div><div class="source-tools"><label for="source-page">頁碼</label><select id="source-page">${(state.doc?.pages||[{page:1},{page:2},{page:3}]).map(p=>`<option value="${p.page}" ${p.page===state.page?'selected':''}>第 ${p.page} 頁</option>`).join('')}</select><span>${state.doc?esc(state.doc.name):'尚未連結 PDF'}</span></div><div id="source-content"></div><div class="source-quote" id="source-quote">${esc(state.quote||'選擇右側「查看原文」，回到對應頁面。頁面定位與文字引用供人工核對。')}</div></section><section class="panel"><div class="tabs">${[['checks','審查結果'],['fields','資料核對'],['totals','案件與計算']].map(([id,label])=>`<button data-action="tab" data-id="${id}" class="${state.tab===id?'active':''}">${label}</button>`).join('')}</div>${state.tab==='checks'?checksView():state.tab==='fields'?fieldsView():totalsView()}<div class="sticky-save"><span class="dirty-indicator">${state.dirty?'● 有尚未儲存的變更':'所有變更已儲存'}</span><button class="primary small" data-action="save">${icon('check')}儲存並重新審查</button></div></section></div></section>`;
}
function renderSource(){const target=$('#source-content');if(!target)return;if(!state.doc){target.innerHTML='<div class="empty">此案件尚未連結 PDF。<br>可從工作台匯入估價書表。</div>';return}if(state.sourceMode==='pdf'){target.innerHTML=`<iframe title="原始估價 PDF 第 ${state.page} 頁" src="/api/documents/${encodeURIComponent(state.current.document_id)}/file#page=${state.page}&toolbar=1"></iframe>`}else{const text=state.doc.pages.find(p=>p.page===state.page)?.text||'此頁沒有可抽取文字；請切換 PDF 檢視或手動輸入。';target.innerHTML=`<pre class="source-text">${esc(text)}</pre>`}}
function checksView(){const checks=state.review.checks.filter(c=>state.filter==='all'||c.status===state.filter);return `<div class="filters">${[['all','全部'],['error','疑似錯誤'],['pending','待確認'],['missing','資料不足'],['pass','通過']].map(([id,label])=>`<button data-action="filter" data-id="${id}" class="${state.filter===id?'active':''}">${label}${id!=='all'?' '+state.review.counts[id]:''}</button>`).join('')}</div><div class="checks">${checks.length?checks.map(c=>`<article class="check"><div class="check-title"><h3>${esc(c.title)}</h3>${pill(c.status)}</div><p>${esc(c.message)}</p>${c.expected!=null?`<div class="comparison"><span><small>原填值</small>${fmt(c.actual)}</span><span class="muted">→</span><span><small>基準 / 計算值</small><b>${fmt(c.expected)}</b></span></div>`:''}<div class="check-bottom"><div class="actions">${c.page?`<button class="ghost small" data-action="source" data-id="${esc(c.id)}">${icon('file')}原文 p.${c.page}</button>`:''}${c.rule_page?`<button class="ghost small" data-action="rule" data-id="${esc(c.factor_id)}">基準 p.${c.rule_page}</button>`:''}</div>${c.status==='error'&&c.expected!=null?`<button class="small" data-action="fix" data-id="${esc(c.id)}">採用建議</button>`:c.factor_id&&c.status!=='pass'?`<button class="small" data-action="edit-factor" data-id="${esc(c.factor_id)}">核對資料</button>`:''}</div></article>`).join(''):'<div class="empty">這個分類沒有檢核項目。</div>'}</div>`}
function fieldsView(){const rules=activeRules().rules.filter(r=>r.scope===state.scope);return `<div class="filters"><button data-action="scope" data-id="individual" class="${state.scope==='individual'?'active':''}">個別因素</button><button data-action="scope" data-id="regional" class="${state.scope==='regional'?'active':''}">區域因素</button><button data-action="ai" style="margin-left:auto">${icon('spark')}AWS AI 抽取</button></div><div class="editor"><p class="smalltext muted">數值請依欄位單位填寫；「無」、空白與免比較分開。確認代表已核對本列原文。欄位異動請先儲存，再重新勾選確認。</p>${rules.map(r=>{let f=state.current.factors.find(f=>f.id===r.id);if(!f){f={id:r.id,subject:null,comparable:null,entered_rate:null,confirmed:false,exempt:false,note:'',subject_grade:null,comparable_grade:null,evidence:{page:r.scope==='individual'?3:1,quote:'',method:'manual'}};state.current.factors.push(f)}const options=r.bands.flatMap(b=>b.values||[]);return `<div class="field-row" id="field-${esc(r.id)}"><h3>${esc(r.name)} <button class="ghost small" data-action="rule" data-id="${esc(r.id)}">查看級距</button></h3><div class="inputs">${['subject','comparable'].map((key,i)=>`<label>${i?'比較標的':'比準地'} ${r.unit?'('+esc(r.unit)+')':''}<input data-factor="${esc(r.id)}" data-key="${key}" value="${esc(f[key])}" placeholder="未填寫" list="values-${esc(r.id)}"></label>`).join('')}<label>修正率 %<input type="number" step="any" data-factor="${esc(r.id)}" data-key="entered_rate" value="${esc(f.entered_rate)}" placeholder="未填"></label></div><datalist id="values-${esc(r.id)}">${options.map(v=>`<option value="${esc(v)}">`).join('')}</datalist>${r.scope==='regional'?`<div class="inputs" style="margin-top:9px">${['subject_grade','comparable_grade'].map((key,i)=>`<label>表 5-2 ${i?'比較標的':'比準地'}等級<select data-factor="${esc(r.id)}" data-key="${key}"><option value="">未填</option>${[...new Set([...r.bands.map(b=>b.label),f[key]].filter(Boolean))].map(v=>`<option ${f[key]===v?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`).join('')}</div>`:''}<div class="field-options"><label><input type="checkbox" data-factor="${esc(r.id)}" data-key="confirmed" ${f.confirmed?'checked':''} ${state.confirmationBlocks.all||state.confirmationBlocks.factors.has(f.id)?'disabled':''}>已核對原文</label><label><input type="checkbox" data-factor="${esc(r.id)}" data-key="exempt" ${f.exempt?'checked':''}>免比較（人工判斷）</label><button class="ghost small" data-action="source" data-id="${esc(r.id)}">p.${f.evidence.page} 原文</button></div><input class="field-note" aria-label="${esc(r.name)} 特殊調整理由" placeholder="特殊調整 / 免比較理由（選填）" data-factor="${esc(r.id)}" data-key="note" value="${esc(f.note)}"></div>`}).join('')}</div>`}
function totalsView(){const c=state.current;return `<div class="editor"><div class="formgrid">${[['title','案件名稱'],['case_number','案件編號'],['valuation_date','估價基準日'],['locality','適用地區'],['land_use','用地類別'],['subject_name','比準地'],['subject_address','比準地詳細地址'],['comparable_name','比較標的'],['comparable_address','比較標的詳細地址'],['subject_section','比準地區段號'],['comparable_section','比較標的區段號']].map(([key,label])=>`<label>${label}<input data-case="${key}" value="${esc(c[key])}"></label>`).join('')}<label class="full">案件評價基準<select data-case="ruleset_id">${state.rulesets.map(r=>`<option value="${esc(r.id)}" ${c.ruleset_id===r.id?'selected':''}>${esc(r.name)} / ${esc(r.version)}</option>`).join('')}</select></label></div><h3 style="margin:27px 0 17px">計算欄位</h3><p class="smalltext muted">目前支援 1 筆比較標的。改值後請先儲存，再重新勾選確認；系統會檢查加總與價格計算。</p><div class="formgrid">${Object.entries(totalNames).map(([key,label])=>`<label>${label}<input type="number" step="any" data-total="${key}" value="${esc(c.totals[key])}"></label>`).join('')}<label class="full"><input type="checkbox" data-case="totals_confirmed" ${c.totals_confirmed?'checked':''} ${state.confirmationBlocks.totals?'disabled':''}>已核對計算欄位及日期調整率</label><label class="full">案件備註<textarea rows="5" data-case="notes">${esc(c.notes)}</textarea></label></div></div>`}
function rulesPage(){const r=state.rulesets.find(r=>r.id===state.rulesetView)||state.rulesets[0];const rules=r.rules.filter(x=>(x.name+x.group+x.scope).includes(state.ruleSearch));return `<div class="title-row"><div><div class="eyebrow">VALUATION STANDARDS</div><h1>評價基準庫</h1><p class="subtitle">級距、矩陣與文件依據，都保存在同一個版本。</p></div><div class="actions"><button data-action="new-rules">${icon('plus')}建立基準版本</button><button class="primary" data-action="ruleset-upload">${icon('upload')}上傳評價基準表</button></div></div><div class="notice info">${esc(r.name)} · v${esc(r.version)} · ${esc(r.locality)} / ${esc(r.land_use)}<br>${esc(r.direction)}。${r.import_kind==='ocr-structured'?'此版本由已確認的 OCR structured ruleset 建立。':'內建基準來自提供範例，非現行通用標準。'}</div><div class="section-head"><select id="ruleset-select" aria-label="選擇基準版本">${state.rulesets.map(x=>`<option value="${esc(x.id)}" ${x.id===r.id?'selected':''}>${esc(x.name)} / ${esc(x.version)}</option>`).join('')}</select>${r.source_document_id?`<a class="smalltext" href="/api/documents/${encodeURIComponent(r.source_document_id)}/file" target="_blank" rel="noopener">開啟此版本原始基準 PDF ↗</a>`:'<a class="smalltext" href="/api/reference/rules" target="_blank" rel="noopener">開啟原始基準 PDF ↗</a>'}</div><div class="rule-grid">${rules.map(x=>`<button class="rule-card" data-action="rule" data-id="${esc(x.id)}"><span class="pill ${x.blocked?'pending':'neutral'}">${x.scope==='regional'?'區域因素':'個別因素'} · ${esc(x.group)}</span><h3>${esc(x.name)}</h3><p>${x.bands.length} 級評價 · 來源第 ${x.source_page} 頁</p>${x.blocked?'<p class="risk" style="margin-top:9px">此因素須人工核對</p>':''}</button>`).join('')}</div>`}
function guide(){return `<div class="title-row"><div><div class="eyebrow">GETTING STARTED</div><h1>使用指南</h1><p class="subtitle">從一份地區基準與題目，到可追溯的審查結果。</p></div></div><div class="panel" style="padding:28px"><div class="formgrid">${[['01 上傳地區基準','上傳評價基準明細表並填寫行政區與適用期間。PaddleOCR 轉成 structured ruleset；核對原文及矩陣方向後，才建立可套用版本及檢索來源。'],['02 上傳題目','選擇已確認的 ruleset 後上傳題目 PDF。系統擷取明確地址、行政區與可唯一對應的因素列，無法判定的資料保持待確認。'],['03 核對填表','逐列檢視比準地、比較標的、修正率與原文。空白不視為零；地址、欄位與 OCR 草稿皆須人工確認。'],['04 匯出成果','優先下載包含所有動態因素的完整審查 Excel；另保留 CSV、JSON、HTML 及既有表3／表4／表5固定模板 Excel。']].map(([title,body])=>`<div class="help-card"><div><h3>${title}</h3><p>${body}</p></div></div>`).join('')}</div><h3 style="margin-top:28px">AWS AI 抽取</h3><p class="smalltext muted">${state.health.ai_configured?'已設定模型：'+esc(state.health.ai_model):'尚未設定模型。'} 使用 AWS Bedrock 與案件選定的基準整理欄位。PDF 辨識在本機執行，只有確認符合競賽上雲規範後才將抽取文字送至 AWS。模型輸出先呈現預覽；套用後仍待人工確認。</p><h3 style="margin-top:25px">範圍與已知限制</h3><p class="smalltext muted">不同地區須使用同類評價基準表格結構；版型差異、OCR 無法唯一定位、manual 因素與一筆以上比較標的仍須人工處理。系統不做 geocoding 或 GIS 自動量距。跨地區完整輸出使用動態 Excel；表3／表4／表5固定模板只填入既有欄位座標，不等同官方 PDF 套印。</p><div class="actions" style="margin-top:20px"><a href="/api/reference/brief" target="_blank" rel="noopener">命題文件 ↗</a><a href="/api/reference/manual" target="_blank" rel="noopener">作業手冊（104 年 3 月版）↗</a><a href="/api/reference/rules" target="_blank" rel="noopener">基準範例 ↗</a></div></div>`}
function modal(title,body,footer=''){const d=$('#dialog');d.className='';d.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="ghost small" data-action="close" aria-label="關閉">${icon('close')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-foot">${footer}</div>`:''}`;if(!d.open)d.showModal()}
function showReviewFactor(id){
 const vm=reviewViewModel(),factor=vm.factors.find(item=>item.id===id);
 if(!factor)return;
 modal(factor.name,`<div class="drawer-status-line"><span>審查狀態</span>${reviewStatus(factor.status)}</div><dl class="factor-detail-grid"><div><dt>因素類別</dt><dd>${displayValue(factor.group)}</dd></div><div><dt>欄位單位</dt><dd>${displayValue(factor.unit)}</dd></div><div><dt>比準地原始值</dt><dd>${displayValue(factor.subjectValue)}</dd></div><div><dt>比較標的原始值</dt><dd>${displayValue(factor.comparableValue)}</dd></div><div><dt>表單等級</dt><dd>${displayPair(factor.enteredSubjectGrade,factor.enteredComparableGrade)}</dd></div><div><dt>系統等級</dt><dd>${displayPair(factor.systemSubjectGrade,factor.systemComparableGrade)}</dd></div><div><dt>表單修正率</dt><dd>${displayRate(factor.enteredRate)}</dd></div><div><dt>系統修正率</dt><dd>${displayRate(factor.expectedRate)}</dd></div></dl><section class="drawer-section"><h3>判定說明</h3><p>${esc(factor.message)}</p></section><section class="drawer-section"><h3>規則來源</h3><p>${displayValue(vm.ruleset.name)} · v${displayValue(vm.ruleset.version)}${factor.sourcePage?` · 第 ${factor.sourcePage} 頁`:''}</p><p class="muted">${displayValue(vm.ruleset.source)}</p></section><section class="drawer-section"><h3>原文依據</h3>${factor.evidence?.quote?`<blockquote>${esc(factor.evidence.quote)}</blockquote><p class="muted">第 ${factor.evidence.page} 頁 · ${esc(factor.evidence.method||'未提供擷取方式')}</p>`:'<p class="muted">目前系統未提供原文依據。</p>'}</section>${factor.matrixAvailable?'':'<div class="notice">目前無法取得修正矩陣。</div>'}`,`<button data-action="edit-factor" data-id="${esc(factor.id)}">核對資料</button>${factor.evidence?.page?`<button data-action="source" data-id="${esc(factor.id)}">查看原文</button>`:''}${factor.matrixAvailable?`<button class="primary" data-action="rule" data-id="${esc(factor.id)}">查看修正矩陣</button>`:''}`);
 $('#dialog').classList.add('review-detail-drawer');
}
function showRule(id){
 const set=state.view==='rules'?(state.rulesets.find(r=>r.id===state.rulesetView)||state.rulesets[0]):activeRules(),r=set?.rules.find(rule=>rule.id===id);
 if(!r)return;
 const desc=b=>{const aliases=b.values?.join('、');if(!r.unit)return aliases||'—';if(aliases&&b.low===0&&b.high==null&&!b.ranges)return aliases;const spans=(b.ranges||[[b.low,b.high]]).map(([lo,hi])=>`${lo} ${r.unit} 以上${hi==null?'':`，未滿 ${hi} ${r.unit}`}`).join('；');return spans+(aliases?'，或 '+aliases:'')};
 const source=set.source_document_id?`/api/documents/${encodeURIComponent(set.source_document_id)}/file#page=${r.source_page}`:`/api/reference/rules#page=${r.source_page}`;
 const check=state.review?.checks.find(item=>item.factor_id===id&&item.subject_grade&&item.comparable_grade),matrix=Array.isArray(r.matrix)?r.matrix:[];
 const matrixView=matrix.length?`<p class="muted">修正率矩陣（%）：列＝比準地，欄＝比較標的</p>${check?`<p class="matrix-selection">目前選取：比準地「${esc(check.subject_grade)}」× 比較標的「${esc(check.comparable_grade)}」</p>`:''}<div class="matrix-scroll"><table class="matrix"><tr><th>比準地 ↓</th>${r.bands.map(b=>`<th class="${check?.comparable_grade===b.label?'matrix-axis-selected':''}">${esc(b.label)}</th>`).join('')}</tr>${matrix.map((row,i)=>`<tr><th class="${check?.subject_grade===r.bands[i]?.label?'matrix-axis-selected':''}">${esc(r.bands[i]?.label)}</th>${row.map((v,j)=>{const rowSelected=check?.subject_grade===r.bands[i]?.label,columnSelected=check?.comparable_grade===r.bands[j]?.label,selected=rowSelected&&columnSelected;return `<td class="${selected?'selected-cell':rowSelected||columnSelected?'selected-axis-cell':''}" ${selected?'aria-current="true"':''}>${fmt(v)}</td>`}).join('')}</tr>`).join('')}</table></div>`:'<div class="notice">目前無法取得修正矩陣。</div>';
 modal(r.name,`${r.warning?`<div class="notice">${esc(r.warning)}</div>`:''}<p>${esc(set.name)} / ${esc(set.version)} · ${r.scope==='regional'?'區域因素':'個別因素'}</p><dl class="rule-bands">${r.bands.map(b=>`<dt>${esc(b.label)}</dt><dd>${esc(desc(b))}</dd>`).join('')}</dl>${matrixView}<p><a href="${source}" target="_blank" rel="noopener">原始基準 PDF，第 ${r.source_page} 頁 ↗</a></p><p class="muted">此版本來源：${esc(set.source||'目前系統未提供詳細規則來源')}</p>`)
}
async function refreshList(){state.cases=await api('/api/cases')}
async function openCase(id){await busy('正在載入案件…',async()=>{if(state.dirty&&!await save())return;const p=await api('/api/cases/'+id);state.current=p.case;state.review=p.review;resetConfirmationBlocks();state.doc=p.case.document_id?await api('/api/documents/'+p.case.document_id):null;state.page=Math.min(3,state.doc?.pages.length||3);state.view='case';state.tab='checks';state.filter='all';state.quote='';state.dirty=false;render();window.scrollTo(0,0)})}
let savingCase=null;
async function save(){
 if(!state.current)return true;
 if(savingCase)return !!await savingCase;
 const root=$('#app'),controls=[...root.querySelectorAll('input,select,textarea,button')].map(el=>[el,el.disabled]);
 root.inert=true;for(const [el] of controls)el.disabled=true;
 savingCase=busy('正在儲存新版本…',async()=>{
  const p=await api('/api/cases/'+state.current.id,{method:'PUT',body:JSON.stringify(state.current)});
  state.current=p.case;state.review=p.review;resetConfirmationBlocks();state.dirty=false;
  await refreshList();render();return true;
 });
 try{return !!await savingCase}finally{savingCase=null;root.inert=false;for(const [el,disabled] of controls)if(el.isConnected)el.disabled=disabled}
}
async function navigate(view){if(state.dirty&&!await save())return;state.view=view;await refreshList();render();window.scrollTo(0,0)}
async function acceptPayload(p){
 if(!p)return [];
 state.current=p.case;state.review=p.review;resetConfirmationBlocks();state.doc=null;state.view='case';state.tab='checks';state.filter='all';state.dirty=false;state.quote='';state.page=3;
 render();window.scrollTo(0,0);
 const [listResult,documentResult]=await Promise.allSettled([refreshList(),p.case.document_id?api('/api/documents/'+p.case.document_id):Promise.resolve(null)]),warnings=[];
 if(listResult.status==='rejected')warnings.push('案件已建立，但案件清單暫時無法更新。');
 if(documentResult.status==='fulfilled')state.doc=documentResult.value;else warnings.push('案件已建立，但原始文件暫時無法載入。');
 state.page=Math.min(3,state.doc?.pages.length||3);render();
 if(warnings.length)toast(warnings.join(' '));
 return warnings;
}
async function createSample(kind){if(state.dirty&&!await save())return;await busy('正在建立範例…',async()=>acceptPayload(await api('/api/samples/'+kind,{method:'POST'})))}
async function aiPreview(approved=false){
 if(!state.health.ai_configured){modal('設定 AWS Bedrock','<p>目前未啟用 Bedrock。PaddleOCR 與規則審查仍可使用。</p><p>請依 README 設定 AWS CLI profile、BEDROCK_MODEL_ID 與 BEDROCK_ENABLED=true。</p>');return}
 if(state.dirty&&!await save())return;
 if(!approved){modal('AWS AI 抽取',`<p>將把此文件的辨識文字傳送至 AWS Bedrock，區域 ${esc(state.health.ai_region)}，模型 ${esc(state.health.ai_model)}。</p><div class="notice">競賽禁止將個人資料、財務資訊等受限資料引入 AWS。題目價格欄位是否例外須依主辦說明；未確認前請使用合成展示資料。</div><label><input type="checkbox" id="cloud-data-approved"> 我已確認這份文件符合競賽上雲規範</label>`,`<button data-action="close">取消</button><button class="primary" data-action="run-ai">開始抽取</button>`);return}
 $('#dialog').close();
 const data=await busy('AWS 模型正在整理欄位，請稍候…',()=>api(`/api/cases/${state.current.id}/ai`,{method:'POST',body:JSON.stringify({revision:state.current.revision,cloud_data_approved:true})}));
 if(!data)return;state.aiDraft=data;
 modal('AI 抽取草稿',`<div class="notice info">${esc(data.message)}<br>勾選要套用的欄位，套用會更新兩側條件與修正率，並重設為待確認。</div>${data.factors.map((f,i)=>`<div class="ai-card"><label><input type="checkbox" data-ai-index="${i}">${esc(activeRules().rules.find(r=>r.id===f.id)?.name||f.id)}</label><p>比準地 ${esc(f.subject??'未辨識')} ／ 比較標的 ${esc(f.comparable??'未辨識')} ／ 修正率 ${fmt(f.entered_rate)}%</p><small>p.${f.evidence.page} · ${esc(f.evidence.quote)}</small></div>`).join('')}`,`<button data-action="close">取消</button><button class="primary" data-action="apply-ai">套用勾選草稿</button>`)
}
function showRulesetUpload(){
 modal('上傳影響地價評價基準明細表',`<div class="workflow-steps"><b>1 上傳基準</b><span>2 上傳題目</span><span>3 核對填表</span><span>4 匯出</span></div><p>請先指定表格應屬的縣市行政區。系統只用它核對標題，不做地址或地理推定。</p><div class="formgrid"><label>縣市行政區<input id="ruleset-locality" placeholder="例如：某縣市某行政區"></label><label>適用起日<input id="ruleset-valid-from" type="date"></label><label>適用迄日（含）<input id="ruleset-valid-to" type="date"></label><label class="full">評價基準明細表 PDF<input id="ruleset-file" type="file" accept="application/pdf,.pdf"></label></div><div class="notice">OCR 結果不會直接成為正式規則。建立前必須核對原文與矩陣方向；無法安全轉換的因素會保留待確認。</div>`,`<button data-action="close">取消</button><button class="primary" data-action="extract-ruleset">開始 OCR 與規則轉換</button>`)
}
function showRulesetDraft(){
 const draft=state.rulesetDraft,candidates=draft.candidates||[];
 modal('確認 structured ruleset 草稿',`<div class="workflow-steps"><b>1 確認基準</b><span>2 上傳題目</span><span>3 核對填表</span><span>4 匯出</span></div><div class="notice info">${esc(draft.message)}</div>${draft.warnings?.length?`<div class="notice">${draft.warnings.map(esc).join('<br>')}</div>`:''}<div class="formgrid"><label class="full">候選基準<select id="ruleset-candidate">${candidates.map((c,i)=>`<option value="${i}">${esc(c.name)} / ${esc(c.version)} · ${c.rules.length} 項因素</option>`).join('')}</select></label><label class="full">來源矩陣方向<select id="matrix-direction"><option value="">請核對表頭後選擇</option><option value="target_row_benchmark_column">來源列＝目標／比較區段；欄＝基準／比準地</option><option value="benchmark_row_target_column">來源列＝基準／比準地；欄＝目標／比較區段</option></select></label></div><details><summary>檢視 structured ruleset JSON</summary><pre class="draft-json">${esc(JSON.stringify(draft.rulesets,null,2))}</pre></details><label style="margin-top:16px"><input id="ruleset-confirmed" type="checkbox">我已核對來源、適用地區、期間與矩陣方向</label>`,`<button data-action="close">稍後處理</button><button class="primary" data-action="confirm-ruleset">建立基準並加入檢索</button>`)
}
function showCaseUpload(rulesetId){
 const selected=rulesetId||state.rulesetView||state.rulesets[0]?.id;
 modal('上傳題目並開始填表',`<div class="workflow-steps"><span>1 已有基準</span><b>2 上傳題目</b><span>3 核對填表</span><span>4 匯出</span></div><p>題目 PDF 會以選定基準整理因素欄位，並嘗試擷取文件中明確出現的詳細地址與縣市行政區。</p><label>套用評價基準<select id="case-upload-ruleset">${state.rulesets.map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(r.name)} / ${esc(r.version)} · ${esc(r.locality)}</option>`).join('')}</select></label><div class="notice">沒有唯一對應的地址、欄位或級距會保持待確認，不會用所選基準的地區假裝成題目辨識結果。</div>`,`<button data-action="close">取消</button><button class="primary" data-action="choose-case-file">選擇題目 PDF</button>`)
}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;e.preventDefault();const a=button.dataset.action,id=button.dataset.id;try{
 if(a==='home'||a==='rules'||a==='guide')return await navigate(a);
 if(a==='close')return $('#dialog').close();
 if(a==='open')return await openCase(id);
 if(a==='open-review-factor')return showReviewFactor(id);
 if(a==='focus-review-factor'){const row=document.getElementById(factorRowId(id));if(row){row.scrollIntoView({behavior:'smooth',block:'center'});row.focus({preventScroll:true});row.classList.add('focus-pulse');setTimeout(()=>row.classList.remove('focus-pulse'),1200)}return}
 if(a==='focus-checks'){state.tab='checks';state.filter=['error','pending','missing','pass'].includes(id)?id:'all';render();document.getElementById('full-review-workspace')?.scrollIntoView({behavior:'smooth',block:'start'});return}
 if(a==='copy'){
  if(state.dirty){toast('尚有未儲存的變更，請先儲存後再複製。');return}
  if(!window.confirm('建立目前已儲存版本的案件副本？副本的人工確認狀態將重設。'))return;
  await busy('正在複製案件…',async()=>{
   const p=await api(`/api/cases/${encodeURIComponent(state.current.id)}/copy`,{method:'POST',body:JSON.stringify({revision:state.current.revision})});
   const warnings=await acceptPayload(p);if(!warnings.length)toast('案件副本已建立，請重新核對確認項目。');
  });return;
 }
 if(a==='ruleset-upload'){if(state.dirty&&!await save())return;showRulesetUpload();return}
 if(a==='extract-ruleset'){
  const file=$('#ruleset-file')?.files[0],locality=$('#ruleset-locality')?.value.trim(),validFrom=$('#ruleset-valid-from')?.value,validTo=$('#ruleset-valid-to')?.value;
  if(!file||!locality||!validFrom||!validTo||validFrom>validTo)throw new Error('請填寫地區、有效期間並選擇基準 PDF。');
  if(file.size>20*1024*1024)throw new Error('PDF 上限 20 MB。');
  $('#dialog').close();
  const query=new URLSearchParams({name:file.name,expected_locality:locality});
  const draft=await busy('正在轉換…',()=>api('/api/ruleset-imports?'+query,{method:'POST',body:file,headers:{'Content-Type':'application/pdf'}}));
  if(!draft)return;state.rulesetDraft={...draft,validFrom,validTo};showRulesetDraft();return;
 }
 if(a==='confirm-ruleset'){
  const draft=state.rulesetDraft,index=Number($('#ruleset-candidate')?.value||0),direction=$('#matrix-direction')?.value;
  if(!draft||!draft.candidates[index])throw new Error('找不到待確認的 ruleset 草稿。');
  if(!direction)throw new Error('請依原表表頭確認矩陣方向。');
  if(!$('#ruleset-confirmed')?.checked)throw new Error('請先勾選人工確認。');
  const result=await busy('正在建立基準版本並加入本機檢索…',()=>api('/api/ruleset-imports/confirm',{method:'POST',body:JSON.stringify({document_id:draft.document_id,candidate:draft.candidates[index],valid_from:draft.validFrom,valid_to:draft.validTo,matrix_direction:direction,confirmed:true})}));
  if(!result)return;state.rulesets=await api('/api/rulesets');state.rulesetView=result.ruleset.id;state.rulesetDraft=null;toast(result.message);showCaseUpload(result.ruleset.id);return;
 }
 if(a==='upload'){if(state.dirty&&!await save())return;showCaseUpload();return}
 if(a==='choose-case-file'){state.pendingRulesetId=$('#case-upload-ruleset')?.value;if(!state.pendingRulesetId)throw new Error('請先選擇評價基準。');$('#dialog').close();$('#pdf-input').click();return}
 if(a==='json-import'){if(state.dirty&&!await save())return;$('#json-input').click();return}
 if(a==='demo')return await createSample('errors');
 if(a==='new'){if(state.dirty&&!await save())return;return await busy('正在建立案件…',()=>api('/api/cases',{method:'POST',body:JSON.stringify({title:'未命名估價案件',factors:[]})}).then(acceptPayload))}
 if(a==='save'){if(await save())toast('已儲存並重新審查。');return}
 if(a==='tab'){state.tab=id;render();return}
 if(a==='filter'){state.filter=id;render();return}
 if(a==='scope'){state.scope=id;render();return}
 if(a==='source-mode'){state.sourceMode=state.sourceMode==='pdf'?'text':'pdf';render();return}
 if(a==='rule')return showRule(id);
 if(a==='source'){const fromDialog=$('#dialog').open;if(fromDialog)$('#dialog').close();const check=state.review.checks.find(c=>c.id===id);const f=state.current.factors.find(f=>f.id===(check?.factor_id||id));state.page=f?.evidence.page||check?.page||3;state.page=Math.min(state.page,state.doc?.pages.length||state.page);state.quote=f?.evidence.quote||check?.message||'';$('#source-page').value=state.page;$('#source-quote').textContent=state.quote;renderSource();if(fromDialog||innerWidth<1150)$('.source-panel').scrollIntoView({behavior:'smooth',block:'start'});return}
 if(a==='edit-factor'){if($('#dialog').open)$('#dialog').close();const r=activeRules().rules.find(r=>r.id===id);state.scope=r.scope;state.tab='fields';render();document.getElementById('field-'+id)?.scrollIntoView({block:'center',behavior:'smooth'});return}
 if(a==='fix'){if(state.dirty){if(await save())toast('已儲存變更並更新建議，請再次選擇要採用的項目。');return}await busy('正在採用建議並重新審查…',async()=>{const p=await api(`/api/cases/${state.current.id}/fix/${encodeURIComponent(id)}`,{method:'POST',body:JSON.stringify({revision:state.current.revision})});state.current=p.case;state.review=p.review;resetConfirmationBlocks();await refreshList();render();toast('已採用建議，修訂紀錄已保存。')});return}
 if(a==='export'){if(state.dirty&&!await save())return;return modal('匯出審查成果',`<p>匯出目前已儲存的版本 ${state.current.revision}。未完成項目會保留在報告中。</p><div class="export-links"><div><strong>完整案件、各地動態因素與審查結果</strong><div class="actions"><button class="primary" data-action="download-export" data-id="review-xlsx">完整審查結果 · Excel</button></div></div>${[['report','審查報告 · HTML'],['forms','整理書表 · HTML'],['csv','審查明細 · CSV'],['json','案件資料 · JSON（可重新匯入）']].map(([kind,label])=>`<a target="_blank" rel="noopener" href="/api/cases/${state.current.id}/export/${kind}">${label} ↗</a>`).join('')}</div><h3>既有固定模板分表</h3><p>表3／表4／表5固定模板仍僅填入已定義的儲存格；不同地區或新增因素請以「完整審查結果 Excel」為準。</p><div class="export-links">${[['table3','表3 地價區段勘查表'],['table4','表4 比較法調查估價表'],['table5','表5 區域因素分析明細表（住宅）']].map(([kind,label])=>`<div><strong>${label}</strong><div class="actions"><button data-action="download-export" data-id="${kind}-xlsx">${label} · Excel</button></div></div>`).join('')}</div><p id="export-status" role="status" aria-live="polite"></p>`)}
 if(a==='download-export'){
   const status=$('#export-status');button.disabled=true;if(status)status.textContent='正在產製檔案…';
   try{
     const response=await fetch(`/api/cases/${state.current.id}/export/${id}?revision=${state.current.revision}`);
     if(!response.ok){const error=await response.json();throw new Error(error.detail||'檔案產製失敗');}
     const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');
     link.href=url;link.download=`${id}-${state.current.id}-r${state.current.revision}.xlsx`;
     document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);
     if(status)status.textContent='檔案已下載。待補與待確認項目請參閱明細。';
   }catch(error){if(status)status.textContent=error.message;else toast(error.message);}finally{button.disabled=false;}return;
 }
 if(a==='audit'){const rows=await api(`/api/cases/${state.current.id}/audit`);return modal('案件修訂紀錄',rows.map(r=>`<div class="audit-row"><div>${esc(r.action)}<p class="muted">${new Date(r.at).toLocaleString('zh-TW')}</p></div><a class="smalltext" target="_blank" rel="noopener" href="/api/cases/${state.current.id}/audit/${r.id}">查看快照 ↗</a></div>`).join(''))}
 if(a==='new-rules'){const r=structuredClone(state.rulesets.find(r=>r.id===state.rulesetView)||state.rulesets[0]);delete r.id;r.name+=' · 修訂';r.version='1.1';return modal('建立新的基準版本',`<p>編輯 JSON 後儲存為獨立版本。既有案件保持原基準；可在案件與計算頁切換。</p><div class="notice">確認來源與適用範圍。修改有單位疑點的規則時，需明確修訂級距、warning 與 blocked；請勿僅取消封鎖。</div><textarea class="code" id="rule-json" aria-label="基準 JSON">${esc(JSON.stringify(r,null,2))}</textarea>`,`<button data-action="close">取消</button><button class="primary" data-action="save-rules">驗證並建立版本</button>`)}
 if(a==='save-rules'){const r=await api('/api/rulesets',{method:'POST',body:JSON.stringify(JSON.parse($('#rule-json').value))});state.rulesets=await api('/api/rulesets');state.rulesetView=r.id;$('#dialog').close();state.view='rules';render();toast('新基準版本已建立。');return}
 if(a==='ai')return await aiPreview();
 if(a==='run-ai'){if(!$('#cloud-data-approved')?.checked){toast('請先確認文件符合上雲規範。');return}return await aiPreview(true)}
 if(a==='apply-ai'){const selected=[...document.querySelectorAll('[data-ai-index]:checked')].map(el=>state.aiDraft.factors[+el.dataset.aiIndex]);if(!selected.length){toast('請先勾選要套用的欄位。');return}if(state.aiDraft.revision!==state.current.revision)throw new Error('案件版本已變更，請重新執行 AI 抽取。');for(const f of selected){const i=state.current.factors.findIndex(v=>v.id===f.id);if(i<0)state.current.factors.push(f);else state.current.factors[i]={...state.current.factors[i],subject:f.subject,comparable:f.comparable,entered_rate:f.entered_rate,evidence:f.evidence,confirmed:false};invalidateConfirmation('factor',f.id)}state.dirty=true;$('#dialog').close();state.tab='fields';render();toast('已套用草稿，請先儲存，再逐列核對並確認。');return}
}catch(error){toast(error.message)}});
document.addEventListener('keydown',e=>{const row=e.target.closest('.factor-review-row[data-action="open-review-factor"]');if(!row||e.target!==row||!['Enter',' '].includes(e.key))return;e.preventDefault();row.click()});
document.addEventListener('input',e=>{
 const t=e.target;
 if(t.id==='case-search'){state.search=t.value;$('#case-list').innerHTML=caseTable();return}
 let changed=false;
 if(t.dataset.factor){
  const f=state.current.factors.find(f=>f.id===t.dataset.factor),key=t.dataset.key,old=f[key];
  f[key]=t.type==='checkbox'?t.checked:key==='entered_rate'?(t.value===''?null:Number(t.value)):key==='note'?t.value:t.value||null;
  if(old!==f[key]){changed=true;if(key!=='confirmed')invalidateConfirmation('factor',f.id)}
 }
 if(t.dataset.total){const key=t.dataset.total,value=t.value===''?null:Number(t.value);if(state.current.totals[key]!==value){state.current.totals[key]=value;changed=true;invalidateConfirmation('totals')}}
 if(t.dataset.case){const key=t.dataset.case,value=t.type==='checkbox'?t.checked:t.value;if(state.current[key]!==value){state.current[key]=value;changed=true;if(confirmationContext.has(key))invalidateConfirmation('all')}}
 if(changed){state.dirty=true;const indicator=$('.dirty-indicator');if(indicator)indicator.textContent='● 有尚未儲存的變更'}
});
document.addEventListener('change',async e=>{if(e.target.id==='source-page'){state.page=Number(e.target.value);renderSource()}if(e.target.id==='ruleset-select'){state.rulesetView=e.target.value;render()}});
$('#pdf-input').addEventListener('change',async e=>{const f=e.target.files[0],rulesetId=state.pendingRulesetId||state.rulesets[0]?.id;e.target.value='';state.pendingRulesetId=null;if(!f)return;if(!rulesetId){toast('請先建立或選擇評價基準。');return}if(f.size>20*1024*1024){toast('PDF 上限為 20 MB。');return}const query=new URLSearchParams({name:f.name,ruleset_id:rulesetId});await busy('正在轉換…',async()=>acceptPayload(await api('/api/documents?'+query,{method:'POST',body:f,headers:{'Content-Type':'application/pdf'}})))});
$('#json-input').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;await busy('正在匯入案件…',async()=>{const data=JSON.parse(await f.text());data.id='';data.revision=0;data.document_id=null;data.source_kind='json';data.title+=' · 匯入';await acceptPayload(await api('/api/cases',{method:'POST',body:JSON.stringify(data)}))})});
window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue=''}});
async function boot(){try{[state.cases,state.rulesets,state.health]=await Promise.all([api('/api/cases'),api('/api/rulesets'),api('/api/health')]);render()}catch(e){$('#app').innerHTML=`<div class="loading"><h2>無法連線到工作台</h2><p>${esc(e.message)}</p><button onclick="location.reload()">重新連線</button></div>`}}
boot();

setupRag({state,api,modal,esc,save});
